CREATE TABLE ai_desktop_design_master_templates (
  master_template_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  domain TEXT NOT NULL CHECK (domain IN ('common', 'application', 'infrastructure')),
  phase TEXT NOT NULL CHECK (phase IN ('common', 'planning', 'requirements', 'basic-design', 'detailed-design', 'implementation', 'test', 'release', 'operation', 'research')),
  document_type TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0 AND sort_order <= 10000),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1 AND version <= 1000),
  content_json TEXT,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  allow_multiple INTEGER NOT NULL DEFAULT 0 CHECK (allow_multiple IN (0, 1)),
  create_by_default INTEGER NOT NULL DEFAULT 0 CHECK (create_by_default IN (0, 1)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (domain, phase, document_type)
);

CREATE INDEX idx_ai_desktop_design_master_templates_display
  ON ai_desktop_design_master_templates(is_active, phase, sort_order, name);

